namespace UnifiedRgb.Core.Effects.Generators;

/// <summary>覆盖轮询 Cover Cycle: The next palette color wipes over the current one along u.</summary>
public sealed class CoverCycleEffect : EffectGenerator, ILoopable
{
    public const string EffectId = "CoverCycle";

    public CoverCycleEffect()
        : base(EffectId, new EffectParamSchema("Cover Cycle", "覆盖轮询", 2, 7, true, true, EffectMath.Trio, true))
    {
    }

    public override void Render(in RenderContext ctx, Span<Rgb> output)
    {
        var ph = ctx.Phase(0.1, 1.0);
        var k = Floor(ph);
        var f = Frac(ph);
