        for (var i = 0; i < output.Length; i++)
        {
            output[i] = ctx.U(i) <= f ? next : cur;
        }
    }

    public double LoopSeconds(in EffectParams p) => LoopPeriod.PerColor(p, 0.1, 1.0);
}
